std::vector<double> reference_bin_edges(std::vector<double> ref_values, int n_bins = 10) {
    std::sort(ref_values.begin(), ref_values.end());
    size_t n = ref_values.size();
    std::vector<double> edges;
    edges.reserve(n_bins - 1);
    for (int k = 1; k < n_bins; ++k) {
        size_t idx = std::min(n - 1, static_cast<size_t>(n * k / n_bins));
        edges.push_back(ref_values[idx]);
    }
    return edges;
}

std::vector<int> bin_with_edges(const std::vector<double>& values, const std::vector<double>& edges) {
    std::vector<int> out;
    out.reserve(values.size());
    for (double v : values) {
        int b = 0;
        while (b < static_cast<int>(edges.size()) && v > edges[b]) ++b;
        out.push_back(b);
    }
    return out;
}

double population_stability_index(const std::vector<int>& ref_bins, const std::vector<int>& curr_bins, int n_bins = 10) {
    std::map<int, int> ref_counts, curr_counts;
    for (int b : ref_bins) ref_counts[b] += 1;
    for (int b : curr_bins) curr_counts[b] += 1;

    size_t n_ref = ref_bins.empty() ? 1 : ref_bins.size();
    size_t n_curr = curr_bins.empty() ? 1 : curr_bins.size();

    double psi = 0.0;
    for (int b = 0; b < n_bins; ++b) {
        double ref_pct = (ref_counts[b] + 1.0) / static_cast<double>(n_ref + n_bins);
        double curr_pct = (curr_counts[b] + 1.0) / static_cast<double>(n_curr + n_bins);
        if (ref_pct <= 0.0) continue;
        double ratio = curr_pct / ref_pct;
        if (ratio > 0.0) psi += (curr_pct - ref_pct) * std::log(ratio);
    }
    return psi;
}

double kolmogorov_smirnov_statistic(const std::vector<double>& ref_vals, const std::vector<double>& curr_vals) {
    std::vector<double> all_vals;
    all_vals.reserve(ref_vals.size() + curr_vals.size());
    for (double v : ref_vals) all_vals.push_back(v);
    for (double v : curr_vals) all_vals.push_back(v);
    std::sort(all_vals.begin(), all_vals.end());
    all_vals.erase(std::unique(all_vals.begin(), all_vals.end()), all_vals.end());

    if (all_vals.empty()) return 0.0;
    double ks = 0.0;
    for (double v : all_vals) {
        size_t ref_le = 0, curr_le = 0;
        for (double rv : ref_vals) if (rv <= v) ++ref_le;
        for (double cv : curr_vals) if (cv <= v) ++curr_le;
        double ref_cdf = ref_vals.empty() ? 0.0 : ref_le / static_cast<double>(ref_vals.size());
        double curr_cdf = curr_vals.empty() ? 0.0 : curr_le / static_cast<double>(curr_vals.size());
        ks = std::max(ks, std::abs(ref_cdf - curr_cdf));
    }
    return ks;
}

int main() {
    std::cout << "Scenario 1: No drift (same distribution)\n";
    auto edges_nd = reference_bin_edges(REF_ND, 10);
    auto ref_bins_nd = bin_with_edges(REF_ND, edges_nd);
    auto curr_bins_nd = bin_with_edges(CURR_ND, edges_nd);

    double psi_no_drift = population_stability_index(ref_bins_nd, curr_bins_nd, 10);
    double ks_no_drift = kolmogorov_smirnov_statistic(REF_ND, CURR_ND);

    std::cout << "  PSI:  " << psi_no_drift << " (threshold: 0.25)\n";
    std::cout << "  KS:   " << ks_no_drift << " (threshold: 0.1)\n";
    std::cout << "  Drift: " << (psi_no_drift > 0.25 ? "Yes" : "No") << "\n";
    assert(psi_no_drift < 0.25);
    assert(ks_no_drift < 0.1);

    std::cout << "\nScenario 2: Planted drift (mean shift +3 SD, variance increase)\n";
    auto edges_d = reference_bin_edges(REF_D, 10);
    auto ref_bins_d = bin_with_edges(REF_D, edges_d);
    auto curr_bins_d = bin_with_edges(CURR_D, edges_d);

    double psi_drift = population_stability_index(ref_bins_d, curr_bins_d, 10);
    double ks_drift = kolmogorov_smirnov_statistic(REF_D, CURR_D);

    std::cout << "  PSI:  " << psi_drift << "\n";
    std::cout << "  KS:   " << ks_drift << " (threshold: 0.1)\n";
    std::cout << "  Drift detected by KS: " << (ks_drift > 0.1 ? "Yes" : "No") << "\n";
    assert(ks_drift > 0.1);
    assert(psi_drift > 0.25);
    assert(psi_drift > psi_no_drift);

    std::cout << "\ndrift_detection_psi.cpp PASS\n";
    return 0;
}